CREATE TABLE `site_content_entries` (
	`key` text PRIMARY KEY NOT NULL,
	`scope` text NOT NULL,
	`route` text NOT NULL,
	`label` text NOT NULL,
	`schema_version` integer DEFAULT 1 NOT NULL,
	`draft_json` text NOT NULL,
	`published_json` text NOT NULL,
	`version` integer DEFAULT 1 NOT NULL,
	`updated_by` integer,
	`updated_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,
	`published_by` integer,
	`published_at` text
);
--> statement-breakpoint
CREATE INDEX `idx_site_content_entries_scope` ON `site_content_entries` (`scope`,`key`);--> statement-breakpoint
CREATE INDEX `idx_site_content_entries_route` ON `site_content_entries` (`route`);--> statement-breakpoint
CREATE TABLE `site_content_revisions` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`entry_key` text NOT NULL,
	`revision_number` integer NOT NULL,
	`snapshot` text NOT NULL,
	`action` text NOT NULL,
	`actor_user_id` integer NOT NULL,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX `site_content_revisions_entry_number_unique` ON `site_content_revisions` (`entry_key`,`revision_number`);--> statement-breakpoint
CREATE INDEX `idx_site_content_revisions_entry_created` ON `site_content_revisions` (`entry_key`,`created_at`);--> statement-breakpoint
